import 'dart:io';
import 'package:ffigen/ffigen.dart';

void main() {
  final root = Platform.script.resolve('../');
  FfiGenerator(
    headers: Headers(
      entryPoints: [root.resolve('native/vitalis_chat_template.h')],
    ),
    functions: Functions(
      include: (declaration) =>
          declaration.originalName == 'vitalis_chat_template_render',
      recordUse: (_) => true,
