      recordUseMapping: root.resolve(
        'lib/src/third_party/vitalis_chat_template.record_use_mapping.g.dart',
      ),
      format: true,
      preamble:
          '// Copyright 2026 VITALIS contributors. MIT license; see LICENSE.\n'
          '// Generated by package:ffigen. Do not edit manually.\n',
    ),
  ).generate(
    libclangDylib: Platform.environment['VITALIS_LIBCLANG'] == null
        ? null
        : Uri.file(Platform.environment['VITALIS_LIBCLANG']!),
  );
